package com.example.starter.arbitration.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 资源租约申请。
 *
 * @param controllerId 控制器ID
 * @param requestId    幂等键：同一 requestId 同参重放返回原结果，异参重放返回409
 * @param resourceId   资源（关节/执行器）标识
 * @param priority     优先级，数值越大越高，严格大于当前持有者可抢占
 * @param leaseMs      租约时长（毫秒）
 */
public record ClaimRequest(
        @NotBlank String controllerId,
        @NotBlank String requestId,
        @NotBlank String resourceId,
        @NotNull Integer priority,
        @NotNull @Min(1) Long leaseMs) {
}

package com.example.starter.arbitration.dto;

/**
 * 租约申请/续期结果。
 *
 * @param claimId        租约ID
 * @param state          租约状态：ACTIVE/RELEASED/PREEMPTED/EXPIRED/ESTOPPED
 * @param leaseExpiresAt 租约到期时刻（epoch毫秒）
 * @param replayed       是否为幂等重放命中（同 requestId 同参数）
 */
public record ClaimResponse(long claimId, String state, long leaseExpiresAt, boolean replayed) {
}

package com.example.starter.arbitration.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 租约续期请求；幂等：新到期时刻不晚于当前到期时刻时为无操作成功。
 *
 * @param controllerId 控制器ID，必须为当前持有者
 * @param resourceId   资源标识
 * @param leaseMs      续期时长（毫秒），自当前时刻起算
 */
public record RenewRequest(
        @NotBlank String controllerId,
        @NotBlank String resourceId,
        @NotNull @Min(1) Long leaseMs) {
}

package com.example.starter.arbitration.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 租约释放请求；幂等：重复释放返回成功，非持有者释放返回409。
 *
 * @param controllerId 控制器ID
 * @param resourceId   资源标识
 */
public record ReleaseRequest(
        @NotBlank String controllerId,
        @NotBlank String resourceId) {
}

package com.example.starter.arbitration.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 运动指令：携带时戳、序列号与目标位置/速度/加速度。
 *
 * @param controllerId 提交控制器ID，必须为资源当前持有者
 * @param resourceId   资源标识
 * @param seq          序列号，按资源+控制器严格递增
 * @param ts           指令时戳（epoch毫秒），必须单调且不允许时钟回拨
 * @param position     目标位置，必须在资源位置边界内
 * @param velocity     目标速度，绝对值不得超过限速
 * @param acceleration 目标加速度，绝对值不得超过限加速度
 */
public record CommandRequest(
        @NotBlank String controllerId,
        @NotBlank String resourceId,
        @NotNull Long seq,
        @NotNull Long ts,
        @NotNull Double position,
        @NotNull Double velocity,
        @NotNull Double acceleration) {
}

package com.example.starter.arbitration.dto;

/**
 * 指令受理结果。
 *
 * @param commandId 指令ID
 * @param status    指令状态：QUEUED 已入待执行队列
 */
public record CommandResponse(long commandId, String status) {
}

